INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LygJJ3ma77L', 1, '{"title":"小柴胡汤","description":"<p>147、$f{小柴胡汤} $m{7味} $u{柴胡}$w{半斤}，$u{黄芩}$w{三两}，$u{人参}$w{三两}，$u{甘草}$w{三两}，$u{半夏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":147,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","黄芩","人参","甘草","半夏","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半斤","weight":800,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '147、$f{小柴胡汤} $m{7味} $u{柴胡}$w{半斤}，$u{黄芩}$w{三两}，$u{人参}$w{三两}，$u{甘草}$w{三两}，$u{半夏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} $s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日三服。', '2024-09-17T01:00:02.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
