INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1UhUFJQNEgW', 1, '{"title":"茯苓泽泻汤","description":"<p>150、$f{茯苓泽泻汤} $m{6味} $a{《外台》云治消渴脉绝，胃反吐食之，有小麦一升。}</p>\n<p>\t$u{茯苓}$w{半斤}，$u{泽泻}$w{四两}，$u{甘草}$w{二两}，$u{桂枝}$w{二两}，$u{白术}$w{三两}，$u{生姜}$w{四两}</p>\n<p>\t$s{右六味}，以水一斗，煮取三升，内泽泻，再煮取二升半。温服八合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":150,"yaoCount":6,"drinkNum":3,"yaoList":["茯苓","泽泻","甘草","桂枝","白术","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"半斤","weight":800,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"四两","weight":400,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":300,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":400,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '150、$f{茯苓泽泻汤} $m{6味} $a{《外台》云治消渴脉绝，胃反吐食之，有小麦一升。} $u{茯苓}$w{半斤}，$u{泽泻}$w{四两}，$u{甘草}$w{二两}，$u{桂枝}$w{二两}，$u{白术}$w{三两}，$u{生姜}$w{四两} $s{右六味}，以水一斗，煮取三升，内泽泻，再煮取二升半。温服八合，日三服。', '2024-09-17T01:00:02.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
