INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AiNuz3m28rK', 1, '{"title":"小承气汤","description":"<p>156、$f{小承气汤} $m{3味} $u{大黄}$w{四两}，$u{厚朴}$w{二两，炙}，$u{枳实}$w{大者三枚，炙}</p>\n<p>\t$s{右三味}，以水四升，煮取一升二合，去滓，分温二服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":156,"yaoCount":3,"drinkNum":2,"yaoList":["大黄","厚朴","枳实"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"二两","weight":200,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"3枚大者","weight":40,"suffix":"","showName":"枳实","extraProcess":"切"}]}}', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '156、$f{小承气汤} $m{3味} $u{大黄}$w{四两}，$u{厚朴}$w{二两，炙}，$u{枳实}$w{大者三枚，炙} $s{右三味}，以水四升，煮取一升二合，去滓，分温二服。', '2024-09-17T01:00:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dh4wSRdoM7k', 1, '{"title":"桃花汤","description":"<p>157、$f{桃花汤} $m{3味} $u{赤石脂}$w{一斤，一半剉，一半筛末}，$u{干姜}$w{一两}，$u{粳米}$w{一升}</p>\n<p>\t$s{右三味}，以水七升，煮米令熟，去滓，温七合，内赤石脂末方寸匕。日三服，若一服愈，余勿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":157,"yaoCount":3,"drinkNum":3,"yaoList":["赤石脂","干姜","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"1rOkrjGOCab","amount":"一斤","weight":1600,"suffix":"","showName":"赤石脂","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"一升","weight":1000,"suffix":"","showName":"粳米","extraProcess":"切"}]}}', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '157、$f{桃花汤} $m{3味} $u{赤石脂}$w{一斤，一半剉，一半筛末}，$u{干姜}$w{一两}，$u{粳米}$w{一升} $s{右三味}，以水七升，煮米令熟，去滓，温七合，内赤石脂末方寸匕。日三服，若一服愈，余勿服。', '2024-09-17T01:00:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nhr1kx9pr5m', 1, '{"title":"白头翁汤","description":"<p>158、$f{白头翁汤} $m{4味} $u{白头翁}$w{二两}，$u{黄连}，$u{黄柏}，$u{秦皮}$w{各三两}</p>\n<p>\t$s{右四味}，以水七升，煮取二升，去滓。温服一升，不愈更服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":158,"yaoCount":4,"drinkNum":2,"yaoList":["白头翁","黄连","黄柏","秦皮"],"fangList":[],"fangYaoList":[{"yaoId":"Nosq7W5OJnv","amount":"二两","weight":200,"suffix":"","showName":"白头翁","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"三两","weight":300,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"三两","weight":300,"suffix":"","showName":"黄柏","extraProcess":"切"},{"yaoId":"Iru92bFSKGK","amount":"三两","weight":300,"suffix":"","showName":"秦皮","extraProcess":"切"}]}}', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '158、$f{白头翁汤} $m{4味} $u{白头翁}$w{二两}，$u{黄连}，$u{黄柏}，$u{秦皮}$w{各三两} $s{右四味}，以水七升，煮取二升，去滓。温服一升，不愈更服。', '2024-09-17T01:00:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
