INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NXyWWaVKxdf', 1, '{"title":"黄芩人参汤","description":"<p>163、$q{《外台》}$f{黄芩人参汤} $m{6味} 治干呕下利。</p>\n<p>\t$u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{桂枝}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半升}</p>\n<p>\t$s{右六味}，以水七升，煮取三升，温分三服。$a{玉函经云人参黄芩汤。注：经查证，玉函经实为黄芩人参汤，有方无条文。本为$f{黄芩汤}，今按此改。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":163,"yaoCount":6,"drinkNum":3,"yaoList":["黄芩","人参","干姜","桂枝","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":100,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '163、$q{《外台》}$f{黄芩人参汤} $m{6味} 治干呕下利。 $u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{桂枝}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半升} $s{右六味}，以水七升，煮取三升，温分三服。$a{玉函经云人参黄芩汤。注：经查证，玉函经实为黄芩人参汤，有方无条文。本为$f{黄芩汤}，今按此改。}', '2024-09-17T01:00:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X6KAd9UmZB0', 1, '{"title":"薏苡附子败酱散","description":"<p>164、$f{薏苡附子败酱散} $m{3味} $u{薏苡仁}$w{十分}，$u{附子}$w{二分}，$u{败酱}$w{五分}</p>\n<p>\t$s{右三味}，杵为末，取方寸匕，以水二升，煎减半，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":164,"yaoCount":3,"drinkNum":20,"yaoList":["薏苡仁","附子","败酱"],"fangList":[],"fangYaoList":[{"yaoId":"rOi0RaqbWeB","amount":"十分","weight":250,"suffix":"","showName":"薏苡仁","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"二分","weight":50,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"oHXa471JIIR","amount":"五分","weight":125,"suffix":"","showName":"败酱","extraProcess":"切"}]}}', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '2024-09-17T01:00:03.000Z', '164、$f{薏苡附子败酱散} $m{3味} $u{薏苡仁}$w{十分}，$u{附子}$w{二分}，$u{败酱}$w{五分} $s{右三味}，杵为末，取方寸匕，以水二升，煎减半，顿服。', '2024-09-17T01:00:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WMEfoeYIuy2', 1, '{"title":"大黄牡丹汤","description":"<p>165、$f{大黄牡丹汤} $m{5味} $u{大黄}$w{四两}，$u{牡丹}$w{一两}，$u{桃仁}$w{五十个}，$u{瓜子}$w{半升}，$u{芒硝}$w{三合}</p>\n<p>\t$s{右五味}，以水六升，煮取一升，去滓，内芒硝，再煎沸。顿服之，有脓当下，如无脓，当下血。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":165,"yaoCount":5,"drinkNum":1,"yaoList":["大黄","牡丹","桃仁","瓜子","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"一两","weight":100,"suffix":"","showName":"牡丹","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"50个","weight":500,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"hIgLFvn83se","amount":"半升","weight":500,"suffix":"","showName":"瓜子","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"三合","weight":300,"suffix":"","showName":"芒硝","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '165、$f{大黄牡丹汤} $m{5味} $u{大黄}$w{四两}，$u{牡丹}$w{一两}，$u{桃仁}$w{五十个}，$u{瓜子}$w{半升}，$u{芒硝}$w{三合} $s{右五味}，以水六升，煮取一升，去滓，内芒硝，再煎沸。顿服之，有脓当下，如无脓，当下血。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2o5KYEF2uvA', 1, '{"title":"王不留行散","description":"<p>166、$f{王不留行散} $m{9味} $u{王不留行}$w{十分，八月八日采}，$u{蒴藋细叶}$w{十分，七月七日采}，$u{桑东南根白皮}$w{十分，三月三日采}，$u{甘草}$w{十八分}，$u{川椒}$w{三分，除目及闭口者，去汗}，$u{黄芩}$w{二分}，$u{干姜}$w{二分}，$u{芍药}$w{二分}，$u{厚朴}$w{二分}</p>\n<p>\t$s{右九味}，桑根皮以上三味烧灰存性，勿令灰过，各别杵筛，合治之为散，服方寸匕。小疮即粉之，大疮但服之，产后亦可服。如风寒，桑东根勿取之。前三物皆阴干百日。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":166,"yaoCount":9,"drinkNum":60,"yaoList":["王不留行","蒴藋细叶","桑东南根白皮","甘草","川椒","黄芩","干姜","芍药","厚朴"],"fangList":[],"fangYaoList":[{"yaoId":"adsjGVQlMyg","amount":"十分","weight":250,"suffix":"","showName":"王不留行","extraProcess":"切"},{"yaoId":"56TOGorPcq0","amount":"十分","weight":250,"suffix":"","showName":"蒴藋细叶","extraProcess":"切"},{"yaoId":"w5Ef5GxAVGF","amount":"十分","weight":250,"suffix":"","showName":"桑东南根白皮","extraProcess":"切"},{"yaoId":null,"amount":"十八","weight":450,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"03dIYYkyQRn","amount":"三分","weight":75,"suffix":"","showName":"川椒","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"二分","weight":50,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"二分","weight":50,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二分","weight":50,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"二分","weight":50,"suffix":"","showName":"厚朴","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '166、$f{王不留行散} $m{9味} $u{王不留行}$w{十分，八月八日采}，$u{蒴藋细叶}$w{十分，七月七日采}，$u{桑东南根白皮}$w{十分，三月三日采}，$u{甘草}$w{十八分}，$u{川椒}$w{三分，除目及闭口者，去汗}，$u{黄芩}$w{二分}，$u{干姜}$w{二分}，$u{芍药}$w{二分}，$u{厚朴}$w{二分} $s{右九味}，桑根皮以上三味烧灰存性，勿令灰过，各别杵筛，合治之为散，服方寸匕。小疮即粉之，大疮但服之，产后亦可服。如风寒，桑东根勿取之。前三物皆阴干百日。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yjrbNy57wWv', 1, '{"title":"排脓散","description":"<p>167、$f{排脓散} $m{3味} $u{枳实}$w{十六枚}，$u{芍药}$w{六分}，$u{桔梗}$w{二分}</p>\n<p>\t$s{右三味}，杵为散，取$u{鸡子黄}$w{一枚}，以药散与鸡黄相等，揉和令相得。和服之，日一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":167,"yaoCount":4,"drinkNum":1,"yaoList":["枳实","芍药","桔梗","鸡子黄"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"16枚(应该是1.5克大的小枳实)","weight":13,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六分","weight":150,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"t7DkIvGNO8b","amount":"二分","weight":50,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":"wDdw8s8LVWE","amount":"1枚","weight":100,"suffix":"","showName":"鸡子黄","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '167、$f{排脓散} $m{3味} $u{枳实}$w{十六枚}，$u{芍药}$w{六分}，$u{桔梗}$w{二分} $s{右三味}，杵为散，取$u{鸡子黄}$w{一枚}，以药散与鸡黄相等，揉和令相得。和服之，日一服。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
