INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('65ZX5Qf7c0m', 1, '{"title":"蜘蛛散","description":"<p>172、$f{蜘蛛散} $m{2味} $u{蜘蛛}$w{十四枚，熬焦}，$u{桂枝}$w{半两}</p>\n<p>\t$s{右二味}，为散，取八分一匕，饮和服，日再服。$u{蜜}丸亦可。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":172,"yaoCount":3,"drinkNum":3,"yaoList":["蜘蛛","桂枝","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"fUxMXp8r0aZ","amount":"14枚","weight":140,"suffix":"","showName":"蜘蛛","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"半两","weight":50,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '172、$f{蜘蛛散} $m{2味} $u{蜘蛛}$w{十四枚，熬焦}，$u{桂枝}$w{半两} $s{右二味}，为散，取八分一匕，饮和服，日再服。$u{蜜}丸亦可。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IXskvKRQ7Uz', 1, '{"title":"甘草粉蜜汤","description":"<p>173、$f{甘草粉蜜汤} $m{3味} $u{甘草}$w{二两}，$u{粉}$w{一两}，$u{蜜}$w{四两}</p>\n<p>\t$s{右三味}，以水三升，先煮甘草，取二升，去滓，内粉、蜜，搅令和，煎如薄粥。温服一升，差即止。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":173,"yaoCount":3,"drinkNum":2,"yaoList":["甘草","粉","蜜"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Ghsn25eutF9","amount":"一两","weight":100,"suffix":"","showName":"粉","extraProcess":"切"},{"yaoId":"IHSagd4ikNY","amount":"四两","weight":400,"suffix":"","showName":"蜜","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '173、$f{甘草粉蜜汤} $m{3味} $u{甘草}$w{二两}，$u{粉}$w{一两}，$u{蜜}$w{四两} $s{右三味}，以水三升，先煮甘草，取二升，去滓，内粉、蜜，搅令和，煎如薄粥。温服一升，差即止。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gy59tosruO9', 1, '{"title":"乌梅丸","description":"<p>174、$f{乌梅丸} $m{10味} $u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{川椒}$w{四两，去汗}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两}</p>\n<p>\t$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":174,"yaoCount":12,"drinkNum":30,"yaoList":["乌梅","细辛","干姜","黄连","当归","附子","川椒","桂枝","人参","黄柏","苦酒","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"ld2CqoYXh1L","amount":"300个","weight":3000,"suffix":"","showName":"乌梅","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"六两","weight":600,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"十两","weight":1000,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"一斤","weight":1600,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"四两","weight":400,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"六两炮","weight":600,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"03dIYYkyQRn","amount":"四两","weight":400,"suffix":"","showName":"川椒","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":600,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"六两","weight":600,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"六两","weight":600,"suffix":"","showName":"黄柏","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '174、$f{乌梅丸} $m{10味} $u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{川椒}$w{四两，去汗}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两} $s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LbnNA0FPW8v', 1, '{"title":"桂枝茯苓丸","description":"<p>175、$f{桂枝茯苓丸} $m{5味} $u{桂枝}，$u{茯苓}，$u{牡丹}$w{去心}，$u{桃仁}$w{去皮尖，熬}，$u{芍药}$w{各等分}</p>\n<p>\t$s{右五味}，末之，炼$u{蜜}和丸，如兔屎大。每日食前服一丸，不知，加至三丸。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":175,"yaoCount":6,"drinkNum":1,"yaoList":["桂枝","茯苓","牡丹","桃仁","芍药","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"1/5兔屎大","weight":2,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"1/5兔屎大","weight":2,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"1/5兔屎大","weight":2,"suffix":"","showName":"牡丹","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"1/5兔屎大","weight":2,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"1/5兔屎大","weight":2,"suffix":"","showName":"芍药","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '175、$f{桂枝茯苓丸} $m{5味} $u{桂枝}，$u{茯苓}，$u{牡丹}$w{去心}，$u{桃仁}$w{去皮尖，熬}，$u{芍药}$w{各等分} $s{右五味}，末之，炼$u{蜜}和丸，如兔屎大。每日食前服一丸，不知，加至三丸。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GZr3gG76P8P', 1, '{"title":"芎归胶艾汤","description":"<p>176、$f{芎归胶艾汤} $m{7味} $a{一方加$u{干姜}$w{一两}。胡氏治妇人胞动，无干姜。}</p>\n<p>\t$u{芎䓖}，$u{阿胶}，$u{甘草}$w{各二两}，$u{艾叶}，$u{当归}$w{各三两}，$u{芍药}$w{四两}，$u{干地黄}$w{四两}</p>\n<p>\t$s{右七味}，以水五升，$u{清酒}$w{三升}，合煮，取三升，去滓，内胶，令消尽。温服一升，日三服，不差更作。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":176,"yaoCount":9,"drinkNum":3,"yaoList":["干姜","芎䓖","阿胶","甘草","艾叶","当归","芍药","干地黄","清酒"],"fangList":[],"fangYaoList":[{"yaoId":"Sfmcy2PNzjm","amount":"二两","weight":200,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"二两","weight":200,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"xfMKrX1fSwJ","amount":"三两","weight":300,"suffix":"","showName":"艾叶","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"三两","weight":300,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"四两","weight":400,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"四两","weight":400,"suffix":"","showName":"干地黄","extraProcess":"切"}]}}', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '2024-09-17T01:00:04.000Z', '176、$f{芎归胶艾汤} $m{7味} $a{一方加$u{干姜}$w{一两}。胡氏治妇人胞动，无干姜。} $u{芎䓖}，$u{阿胶}，$u{甘草}$w{各二两}，$u{艾叶}，$u{当归}$w{各三两}，$u{芍药}$w{四两}，$u{干地黄}$w{四两} $s{右七味}，以水五升，$u{清酒}$w{三升}，合煮，取三升，去滓，内胶，令消尽。温服一升，日三服，不差更作。', '2024-09-17T01:00:04.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
