INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vDbkYtH8ZPW', 1, '{"title":"葵子茯苓散","description":"<p>180、$f{葵子茯苓散} $m{2味} $u{葵子}$w{一斤}，$u{茯苓}$w{三两}</p>\n<p>\t$s{右二味}，杵为散，饮服方寸匕。日三服，小便利则愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":180,"yaoCount":2,"drinkNum":100,"yaoList":["葵子","茯苓"],"fangList":[],"fangYaoList":[{"yaoId":"4WqGFUUR22E","amount":"一斤","weight":1600,"suffix":"","showName":"葵子","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '180、$f{葵子茯苓散} $m{2味} $u{葵子}$w{一斤}，$u{茯苓}$w{三两} $s{右二味}，杵为散，饮服方寸匕。日三服，小便利则愈。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cuKRLI1hVX7', 1, '{"title":"当归散","description":"<p>181、$f{当归散} $m{5味} $u{当归}，$u{黄芩}，$u{芍药}，$u{芎䓖}$w{各一斤}，$u{白术}$w{半斤}</p>\n<p>\t$s{右五味}，杵为散，$u{酒}饮服方寸匕，日再服。妊娠常服即易产，胎无疾苦。产后百病悉主之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":181,"yaoCount":6,"drinkNum":300,"yaoList":["当归","黄芩","芍药","芎䓖","白术","酒"],"fangList":[],"fangYaoList":[{"yaoId":"JFnirDnffR9","amount":"一斤","weight":1600,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"一斤","weight":1600,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"一斤","weight":1600,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"一斤","weight":1600,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"半斤","weight":800,"suffix":"","showName":"白术","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '181、$f{当归散} $m{5味} $u{当归}，$u{黄芩}，$u{芍药}，$u{芎䓖}$w{各一斤}，$u{白术}$w{半斤} $s{右五味}，杵为散，$u{酒}饮服方寸匕，日再服。妊娠常服即易产，胎无疾苦。产后百病悉主之。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SoJ70dZ5HHQ', 1, '{"title":"白术散","description":"<p>182、$f{白术散} $m{4味} $u{白术}$w{四分}，$u{芎䓖}$w{四分}，$u{蜀椒}$w{三分，去汗}，$u{牡蛎}$w{二分}</p>\n<p>\t$s{右四味}，杵为散，$u{酒}服一钱匕，日三服，夜一服。但苦痛，加$u{芍药}；心下毒痛，倍加$u{芎䓖}；心烦吐痛，不能食饮，加$u{细辛}$w{一两}、$u{半夏}$w{大者二十枚}。服之后，更以$u{醋浆水}服之。若呕，以醋浆水服之复不解者，$u{小麦汁}服之；已后渴者，$u{大麦粥}服之。病虽愈，服之勿置。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":182,"yaoCount":4,"drinkNum":15,"yaoList":["白术","芎䓖","蜀椒","牡蛎","酒","芍药","细辛","半夏","醋浆水","小麦汁","大麦粥"],"fangList":[],"fangYaoList":[{"yaoId":"UIYZOmiE2xW","amount":"四分","weight":100,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"四分($x{心下毒痛倍加})","weight":100,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"03dIYYkyQRn","amount":"三分","weight":75,"suffix":"","showName":"蜀椒","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"二分","weight":50,"suffix":"","showName":"牡蛎","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '182、$f{白术散} $m{4味} $u{白术}$w{四分}，$u{芎䓖}$w{四分}，$u{蜀椒}$w{三分，去汗}，$u{牡蛎}$w{二分} $s{右四味}，杵为散，$u{酒}服一钱匕，日三服，夜一服。但苦痛，加$u{芍药}；心下毒痛，倍加$u{芎䓖}；心烦吐痛，不能食饮，加$u{细辛}$w{一两}、$u{半夏}$w{大者二十枚}。服之后，更以$u{醋浆水}服之。若呕，以醋浆水服之复不解者，$u{小麦汁}服之；已后渴者，$u{大麦粥}服之。病虽愈，服之勿置。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wyHq5H9jbVO', 1, '{"title":"枳实芍药散","description":"<p>183、$f{枳实芍药散} $m{2味} $u{枳实}$w{烧令黑，勿太过}，$u{芍药}$w{等分}</p>\n<p>\t$s{右二味}，杵为散。服方寸匕，日三服，并主痈脓，以$u{麦粥}下之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":183,"yaoCount":3,"drinkNum":1,"yaoList":["枳实","芍药","麦粥"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"1/2方寸匕","weight":3,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"1/2方寸匕","weight":3,"suffix":"","showName":"芍药","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '183、$f{枳实芍药散} $m{2味} $u{枳实}$w{烧令黑，勿太过}，$u{芍药}$w{等分} $s{右二味}，杵为散。服方寸匕，日三服，并主痈脓，以$u{麦粥}下之。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cpCyW0KWGsU', 1, '{"title":"下瘀血汤","description":"<p>184、$f{下瘀血汤} $m{3味} $u{大黄}$w{二两}，$u{桃仁}$w{二十枚}，$u{䗪虫}$w{二十枚，熬，去足}</p>\n<p>\t$s{右三味}，末之，炼$u{蜜}和为四丸，以$u{酒}$w{一升}，煎一丸，取八合。顿服之，新血下如豚肝。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":184,"yaoCount":5,"drinkNum":4,"yaoList":["大黄","桃仁","䗪虫","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"二两","weight":200,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"20枚","weight":200,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"nMnl8EhuWTn","amount":"20枚","weight":60,"suffix":"","showName":"䗪虫","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '184、$f{下瘀血汤} $m{3味} $u{大黄}$w{二两}，$u{桃仁}$w{二十枚}，$u{䗪虫}$w{二十枚，熬，去足} $s{右三味}，末之，炼$u{蜜}和为四丸，以$u{酒}$w{一升}，煎一丸，取八合。顿服之，新血下如豚肝。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G4pg5B3Q3iE', 1, '{"title":"竹叶汤","description":"<p>185、$f{竹叶汤} $m{10味} $u{竹叶}$w{一把}，$u{葛根}$w{三两}，$u{防风}，$u{桔梗}，$u{桂枝}，$u{人参}，$u{甘草}$w{各一两}，$u{附子}$w{一枚，炮}，$u{大枣}$w{十五枚}，$u{生姜}$w{五两}</p>\n<p>\t$s{右十味}，以水一斗，煮取二升半，分温三服，温覆使汗出。颈项强，用$u{大附子}$w{一枚，破之如豆大}，煎药，扬去沫。呕者，加$u{半夏}$w{半升洗}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":185,"yaoCount":11,"drinkNum":3,"yaoList":["竹叶","葛根","防风","桔梗","桂枝","人参","甘草","附子","大枣","生姜","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"AAufH0ElVIH","amount":"一把","weight":100,"suffix":"","showName":"竹叶","extraProcess":"切"},{"yaoId":"MzvPguhXJ5G","amount":"三两","weight":300,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":"blvt71sB8Zu","amount":"一两","weight":100,"suffix":"","showName":"防风","extraProcess":"切"},{"yaoId":"t7DkIvGNO8b","amount":"一两","weight":100,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":100,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":100,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚炮($x{颈项强用大者})","weight":100,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '185、$f{竹叶汤} $m{10味} $u{竹叶}$w{一把}，$u{葛根}$w{三两}，$u{防风}，$u{桔梗}，$u{桂枝}，$u{人参}，$u{甘草}$w{各一两}，$u{附子}$w{一枚，炮}，$u{大枣}$w{十五枚}，$u{生姜}$w{五两} $s{右十味}，以水一斗，煮取二升半，分温三服，温覆使汗出。颈项强，用$u{大附子}$w{一枚，破之如豆大}，煎药，扬去沫。呕者，加$u{半夏}$w{半升洗}。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mRsd7MLdDHE', 1, '{"title":"竹皮大丸","description":"<p>186、$f{竹皮大丸} $m{5味} $u{生竹茹}$w{二分}，$u{石膏}$w{二分}，$u{桂枝}$w{一分}，$u{甘草}$w{七分}，$u{白薇}$w{一分}</p>\n<p>\t$s{右五味}，末之，$u{枣肉}和丸弹子大。以饮服一丸，日三、夜二服。有热者，$w{倍}$u{白薇}，烦喘者，加$u{柏实}$w{一分}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":186,"yaoCount":6,"drinkNum":10,"yaoList":["生竹茹","石膏","桂枝","甘草","白薇","柏实","枣肉"],"fangList":[],"fangYaoList":[{"yaoId":"aDnno23iRr4","amount":"二分","weight":50,"suffix":"","showName":"生竹茹","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"二分","weight":50,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一分","weight":25,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"七分","weight":175,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"uwe852yGS58","amount":"一分($x{有热者倍之})","weight":25,"suffix":"","showName":"白薇","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '186、$f{竹皮大丸} $m{5味} $u{生竹茹}$w{二分}，$u{石膏}$w{二分}，$u{桂枝}$w{一分}，$u{甘草}$w{七分}，$u{白薇}$w{一分} $s{右五味}，末之，$u{枣肉}和丸弹子大。以饮服一丸，日三、夜二服。有热者，$w{倍}$u{白薇}，烦喘者，加$u{柏实}$w{一分}。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5ODePWUPubu', 1, '{"title":"白头翁加甘草阿胶汤","description":"<p>187、$f{白头翁加甘草阿胶汤} $m{6味} $u{白头翁}$w{二两}，$u{黄连}，$u{柏皮}，$u{秦皮}$w{各三两}，$u{甘草}$w{二两}，$u{阿胶}$w{二两}</p>\n<p>\t$s{右六味}，以水七升，煮取二升半，内胶，令消尽，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":187,"yaoCount":6,"drinkNum":3,"yaoList":["白头翁","黄连","柏皮","秦皮","甘草","阿胶"],"fangList":[],"fangYaoList":[{"yaoId":"Nosq7W5OJnv","amount":"二两","weight":200,"suffix":"","showName":"白头翁","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"三两","weight":300,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"三两","weight":300,"suffix":"","showName":"柏皮","extraProcess":"切"},{"yaoId":"Iru92bFSKGK","amount":"三两","weight":300,"suffix":"","showName":"秦皮","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"二两","weight":200,"suffix":"","showName":"阿胶","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '187、$f{白头翁加甘草阿胶汤} $m{6味} $u{白头翁}$w{二两}，$u{黄连}，$u{柏皮}，$u{秦皮}$w{各三两}，$u{甘草}$w{二两}，$u{阿胶}$w{二两} $s{右六味}，以水七升，煮取二升半，内胶，令消尽，分温三服。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k8oloqQgZSO', 1, '{"title":"三物黄芩汤","description":"<p>188、$q{附方《千金》}$f{三物黄芩汤} $m{3味} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。</p>\n<p>\t$u{黄芩}$w{一两}，$u{苦参}$w{二两}，$u{干地黄}$w{四两}</p>\n<p>\t$s{右三味}，以水八升，煮取二升。温服一升，多吐下虫。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":188,"yaoCount":3,"drinkNum":2,"yaoList":["黄芩","苦参","干地黄"],"fangList":[],"fangYaoList":[{"yaoId":"fd3riAoOlLa","amount":"一两","weight":100,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"udN4qy4NAcw","amount":"二两","weight":200,"suffix":"","showName":"苦参","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"四两","weight":400,"suffix":"","showName":"干地黄","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '188、$q{附方《千金》}$f{三物黄芩汤} $m{3味} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。 $u{黄芩}$w{一两}，$u{苦参}$w{二两}，$u{干地黄}$w{四两} $s{右三味}，以水八升，煮取二升。温服一升，多吐下虫。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gWwzm6FdOYI', 1, '{"title":"当归建中汤","description":"<p>189、$q{《千金》}内补$f{当归建中汤} $m{6味} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。</p>\n<p>\t$u{当归}$w{四两}，$u{桂枝}$w{三两}，$u{芍药}$w{六两}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右六味}，以水一斗，煮取三升。分温三服，一日令尽。若大虚，加$u{饴糖}$w{六两}，汤成，内之于火上暖，令饴消。若去血过多，崩伤内衄不止，加$u{地黄}$w{六两}、$u{阿胶}$w{二两}，合八味，汤成，内阿胶。若无当归，以$u{芎䓖}代之；若无生姜，以$u{干姜}代之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":189,"yaoCount":11,"drinkNum":3,"yaoList":["当归","桂枝","芍药","生姜","甘草","大枣","饴糖","地黄","阿胶","芎䓖","干姜"],"fangList":[],"fangYaoList":[{"yaoId":"JFnirDnffR9","amount":"四两","weight":400,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":600,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '189、$q{《千金》}内补$f{当归建中汤} $m{6味} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。 $u{当归}$w{四两}，$u{桂枝}$w{三两}，$u{芍药}$w{六两}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚} $s{右六味}，以水一斗，煮取三升。分温三服，一日令尽。若大虚，加$u{饴糖}$w{六两}，汤成，内之于火上暖，令饴消。若去血过多，崩伤内衄不止，加$u{地黄}$w{六两}、$u{阿胶}$w{二两}，合八味，汤成，内阿胶。若无当归，以$u{芎䓖}代之；若无生姜，以$u{干姜}代之。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vFaqx8trb0y', 1, '{"title":"半夏厚朴汤","description":"<p>190、$f{半夏厚朴汤} $m{5味} $a{$q{《千金》}作胸满，心下坚，咽中帖帖，如有炙肉，吐之不出，吞之不下。}</p>\n<p>\t$u{半夏}$w{一升}，$u{厚朴}$w{三两}，$u{茯苓}$w{四两}，$u{生姜}$w{五两}，$u{干苏叶}$w{二两}</p>\n<p>\t$s{右五味}，以水七升，煮取四升。分温四服，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":190,"yaoCount":5,"drinkNum":4,"yaoList":["半夏","厚朴","茯苓","生姜","干苏叶"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"一升","weight":1000,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"三两","weight":300,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"四两","weight":400,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"N3dS9Qrr2yS","amount":"二两","weight":200,"suffix":"","showName":"干苏叶","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '190、$f{半夏厚朴汤} $m{5味} $a{$q{《千金》}作胸满，心下坚，咽中帖帖，如有炙肉，吐之不出，吞之不下。} $u{半夏}$w{一升}，$u{厚朴}$w{三两}，$u{茯苓}$w{四两}，$u{生姜}$w{五两}，$u{干苏叶}$w{二两} $s{右五味}，以水七升，煮取四升。分温四服，日三、夜一服。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6EX4p4E0VjF', 1, '{"title":"甘麦大枣汤","description":"<p>191、$f{甘麦大枣汤} $m{3味} $u{甘草}$w{三两}，$u{小麦}$w{一升}，$u{大枣}$w{十枚}</p>\n<p>\t$s{右三味}，以水六升，煮取三升，温分三服。亦补脾气。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":191,"yaoCount":3,"drinkNum":3,"yaoList":["甘草","小麦","大枣"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"CdBvjhzVtG6","amount":"一升","weight":1000,"suffix":"","showName":"小麦","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚","weight":100,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '191、$f{甘麦大枣汤} $m{3味} $u{甘草}$w{三两}，$u{小麦}$w{一升}，$u{大枣}$w{十枚} $s{右三味}，以水六升，煮取三升，温分三服。亦补脾气。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xuHLPQdjDTj', 1, '{"title":"温经汤","description":"<p>192、$f{温经汤} $m{12味} $u{吴茱萸}$w{三两}，$u{当归}，$u{芎䓖}，$u{芍药}$w{各二两}，$u{人参}，$u{桂枝}，$u{阿胶}，$u{牡丹}$w{去心}，$u{生姜}，$u{甘草}$w{各二两}，$u{半夏}$w{半升}，$u{麦门冬}$w{一升，去心}</p>\n<p>\t$s{右十二味}，以水一斗，煮取三升，分温三服。亦主妇人少腹寒，久不受胎，兼取崩中去血，或月水来过多，及至期不来。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":192,"yaoCount":12,"drinkNum":3,"yaoList":["吴茱萸","当归","芎䓖","芍药","人参","桂枝","阿胶","牡丹","生姜","甘草","半夏","麦门冬"],"fangList":[],"fangYaoList":[{"yaoId":"ZJN7O318dPD","amount":"三两","weight":300,"suffix":"","showName":"吴茱萸","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"二两","weight":200,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"二两","weight":200,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"二两","weight":200,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"二两","weight":200,"suffix":"","showName":"牡丹","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"二两","weight":200,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"DDXydmiFQLK","amount":"一升","weight":600,"suffix":"","showName":"麦门冬","extraProcess":"切"}]}}', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '2024-09-17T01:00:05.000Z', '192、$f{温经汤} $m{12味} $u{吴茱萸}$w{三两}，$u{当归}，$u{芎䓖}，$u{芍药}$w{各二两}，$u{人参}，$u{桂枝}，$u{阿胶}，$u{牡丹}$w{去心}，$u{生姜}，$u{甘草}$w{各二两}，$u{半夏}$w{半升}，$u{麦门冬}$w{一升，去心} $s{右十二味}，以水一斗，煮取三升，分温三服。亦主妇人少腹寒，久不受胎，兼取崩中去血，或月水来过多，及至期不来。', '2024-09-17T01:00:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D6VN8S6Uxne', 1, '{"title":"土瓜根散","description":"<p>193、$f{土瓜根散} $m{4味} $a{阴㿗肿亦主之。}</p>\n<p>\t$u{土瓜根}，$u{芍药}，$u{桂枝}，$u{䗪虫}$w{各三分}</p>\n<p>\t$s{右四味}，杵为散。$u{酒}服方寸匕，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":193,"yaoCount":5,"drinkNum":12,"yaoList":["土瓜根","芍药","桂枝","䗪虫","酒"],"fangList":[],"fangYaoList":[{"yaoId":"jmwsTRL4bR2","amount":"三分","weight":75,"suffix":"","showName":"土瓜根","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三分","weight":75,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":75,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"nMnl8EhuWTn","amount":"三分","weight":75,"suffix":"","showName":"䗪虫","extraProcess":"切"}]}}', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '193、$f{土瓜根散} $m{4味} $a{阴㿗肿亦主之。} $u{土瓜根}，$u{芍药}，$u{桂枝}，$u{䗪虫}$w{各三分} $s{右四味}，杵为散。$u{酒}服方寸匕，日三服。', '2024-09-17T01:00:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
