INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r3pScP24scj', 1, '{"title":"抵当汤","description":"<p>196、$f{抵当汤} $m{4味} $u{水蛭}$w{三十个，熬}，$u{虻虫}$w{三十枚，熬，去翅足}，$u{桃仁}$w{二十个，去皮尖}，$u{大黄}$w{三两，$u{酒}浸}</p>\n<p>\t$s{右四味}，为末，以水五升，煮取三升，去滓，温服一升。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":196,"yaoCount":5,"drinkNum":3,"yaoList":["水蛭","虻虫","桃仁","大黄","酒"],"fangList":[],"fangYaoList":[{"yaoId":"biroLUs3POn","amount":"30个","weight":300,"suffix":"","showName":"水蛭","extraProcess":"切"},{"yaoId":"L1yNgzB2bxB","amount":"30枚","weight":300,"suffix":"","showName":"虻虫","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"20个","weight":200,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"三两","weight":300,"suffix":"","showName":"大黄","extraProcess":"切"}]}}', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '196、$f{抵当汤} $m{4味} $u{水蛭}$w{三十个，熬}，$u{虻虫}$w{三十枚，熬，去翅足}，$u{桃仁}$w{二十个，去皮尖}，$u{大黄}$w{三两，$u{酒}浸} $s{右四味}，为末，以水五升，煮取三升，去滓，温服一升。', '2024-09-17T01:00:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdrooaucz9d', 1, '{"title":"矾石丸","description":"<p>197、$f{矾石丸} $m{2味} $u{矾石}$w{三分，烧}，$u{杏仁}$w{一分}</p>\n<p>\t$s{右二味}，末之，炼$u{蜜}和丸枣核大，内脏中，剧者再内之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":197,"yaoCount":3,"drinkNum":4,"yaoList":["矾石","杏仁","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"ozDrmO1Ighz","amount":"三分","weight":75,"suffix":"","showName":"矾石","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"一分","weight":25,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '197、$f{矾石丸} $m{2味} $u{矾石}$w{三分，烧}，$u{杏仁}$w{一分} $s{右二味}，末之，炼$u{蜜}和丸枣核大，内脏中，剧者再内之。', '2024-09-17T01:00:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uGy7sbgcOG6', 1, '{"title":"红蓝花酒","description":"<p>198、$f{红蓝花酒} $m{1味} $u{红蓝花}$w{一两}</p>\n<p>\t$s{右一味}，以$u{酒}$w{一大升}，煎减半。顿服一半，未止，再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":198,"yaoCount":2,"drinkNum":2,"yaoList":["红蓝花","酒"],"fangList":[],"fangYaoList":[{"yaoId":"c5sh4uVB3zl","amount":"一两","weight":100,"suffix":"","showName":"红蓝花","extraProcess":"切"},{"yaoId":"JMpy06saY9b","amount":"一升","weight":1000,"suffix":"","showName":"酒","extraProcess":"切"}]}}', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '198、$f{红蓝花酒} $m{1味} $u{红蓝花}$w{一两} $s{右一味}，以$u{酒}$w{一大升}，煎减半。顿服一半，未止，再服。', '2024-09-17T01:00:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a2v5iyMKC1D', 1, '{"title":"肾气丸","description":"<p>199、$f{肾气丸} $m{8味} $u{干地黄}$w{八两}，$u{薯蓣}$w{四两}，$u{山茱萸}$w{四两}，$u{泽泻}$w{三两}，$u{茯苓}$w{三两}，$u{牡丹皮}$w{三两}，$u{桂枝}，$u{附子}$w{炮，各一两}</p>\n<p>\t$s{右八味}，末之，炼$u{蜜}和丸梧子大。$u{酒}下十五丸，加至二十五丸，日再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":199,"yaoCount":10,"drinkNum":30,"yaoList":["干地黄","薯蓣","山茱萸","泽泻","茯苓","牡丹皮","桂枝","附子","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"B2o1hdSD6X1","amount":"八两","weight":800,"suffix":"","showName":"干地黄","extraProcess":"切"},{"yaoId":"n7KV9vTrthx","amount":"四两","weight":400,"suffix":"","showName":"薯蓣","extraProcess":"切"},{"yaoId":"ASxxg5RfLMb","amount":"四两","weight":400,"suffix":"","showName":"山茱萸","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"三两","weight":300,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"三两","weight":300,"suffix":"","showName":"牡丹皮","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":100,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"一两炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '2024-09-17T01:00:06.000Z', '199、$f{肾气丸} $m{8味} $u{干地黄}$w{八两}，$u{薯蓣}$w{四两}，$u{山茱萸}$w{四两}，$u{泽泻}$w{三两}，$u{茯苓}$w{三两}，$u{牡丹皮}$w{三两}，$u{桂枝}，$u{附子}$w{炮，各一两} $s{右八味}，末之，炼$u{蜜}和丸梧子大。$u{酒}下十五丸，加至二十五丸，日再服。', '2024-09-17T01:00:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
